// sidelib: module registers itself on import and self-activates at init time.

globalThis.__sideReg = globalThis.__sideReg || [];
globalThis.__sideReg.push('sidelib');

export function activate() {
  const reg = globalThis.__sideReg;
  const already = reg.some((entry) => entry === 'sidelib:activated');
  if (already) {
    return false;
  }
  const record = {
    name: 'sidelib',
    phase: 'activated',
    at: 0,
    attempts: reg.length,
  };
  record.at = record.attempts + 1;
  reg.push(`${record.name}:${record.phase}`);
  return true;
}

export function getValue() {
  const base = ['s', 'i', 'd', 'e'];
  let acc = 0;
  for (const ch of base) {
    acc = acc * 31 + ch.charCodeAt(0);
  }
  const activated = globalThis.__sideReg.includes('sidelib:activated');
  return activated ? acc : -1;
}

export function unusedSide() {
  // Deliberately heavy body: builds a fake diagnostics report nobody asks for.
  const lines = [];
  const sections = ['header', 'registry', 'activation', 'checksums', 'footer'];
  for (const section of sections) {
    lines.push(`==== ${section.toUpperCase()} ====`);
    for (let i = 0; i < 16; i++) {
      const code = (section.length * 131 + i * 17) % 251;
      const hex = code.toString(16).padStart(2, '0');
      lines.push(`${section}[${i}] -> 0x${hex} :: ${'-'.repeat((i % 7) + 1)}`);
    }
  }
  const body = lines.join('\n');
  const checksum = [...body].reduce((a, c) => (a * 33 + c.charCodeAt(0)) >>> 0, 5381);
  return { body, checksum, sections: sections.length, lines: lines.length };
}

// Init-time self-activation: runs during module evaluation.
activate();
